mapper.insert:
INSERT INTO r_board(user_id, r_board_title, r_board_content)
VALUES (
#{userId},
#{rBoardTitle},
#{rBoardContent}
)

mapper.update:
UPDATE r_board
SET is_active = 0
WHERE r_board_id = #{rBoardId}

UPDATE r_board
SET like_count = like_count + 1
WHERE r_board_id = #{rBoardId}

mapper.select:
SELECT like_count
FROM r_board
WHERE r_board_id = #{rBoardId}

SELECT COUNT(*)
FROM r_board_like
WHERE r_board_id = #{rBoardId}
AND user_id = #{userId}
